#!/usr/bin/env bash
# ⑤ 4차 텍스트 기반 실측 — R1(셸 19파일 메뉴·배지·☰·칩) · R2(로그인 5상태) · R3(셀 버튼 px) · R6(title) · N5/N11(권한 열) · S5/S6 처리 중 라벨 · 5셀/6셀 title 전수
B="$HOME/.claude/skills/gstack/browse/dist/browse"
W="C:/Projects/Active/교대근무관리 시스템/시안/2026-09-02-2차HTML"
J() { "$B" js "$1" 2>/dev/null | grep -v "BEGIN\|END" | grep -v '^\s*$'; }
G() { "$B" goto "file:///$W/$1" >/dev/null 2>&1; "$B" wait --load >/dev/null 2>&1; }
P() { "$B" press "$1" >/dev/null 2>&1; }
"$B" viewport 1440x900 >/dev/null 2>&1

echo "=============== R1·N11 셸 19파일: 그룹 머리·배지·아이콘·☰·역할 칩 (상태별) ==============="
for f in 00-shell-1 00-shell-2 04-sites-1 04-sites-2 06-employees-1 06-employees-2 06-employees-3 07-schedule-1 07-schedule-2 07-schedule-3 09-allowance-1 09-allowance-2 09-allowance-3 10-dashboard-1 11-operations-1 11-operations-2 11-operations-3 11-operations-4 12-access-logs-1; do
  G "$f.html"
  J "(()=>{return [...document.querySelectorAll('.state-wrapper')].map(w=>{const s=w.querySelector('.sidebar');if(!s)return w.id+' 셸없음';const heads=[...s.querySelectorAll('.nav-group-header')].map(e=>e.textContent.trim()+(e.offsetParent!==null?'':'(숨김)'));const items=[...s.querySelectorAll('.nav-item')].map(a=>{const ic=(a.querySelector('.material-symbols-outlined')||{textContent:''}).textContent.trim();const t=[...a.querySelectorAll('span')].filter(x=>!x.classList.contains('material-symbols-outlined')&&!x.classList.contains('nav-badge')&&!x.classList.contains('nav-dot-badge')).map(x=>x.textContent.trim()).join('');const b=a.querySelector('.nav-badge,.nav-dot-badge');return ic+':'+t+(b?'['+b.textContent.trim()+'|'+(b.title||'')+']':'')+(a.classList.contains('active')?'*':'')+(a.getAttribute('aria-current')==='page'?'^':'');});const tg=w.querySelector('.btn-sidebar-toggle');const chip=(w.querySelector('.role-badge')||{textContent:'?'}).textContent.trim();const user=(w.querySelector('.user-info-btn')||{textContent:'?'}).textContent.replace(/\s+/g,' ').trim();return w.id+' heads='+heads.join('/')+' | items='+items.join(' ')+' | ☰='+(tg?tg.getAttribute('aria-label'):'없음')+' | chip='+chip+' user='+user;}).join('\n');})()"
done

echo "=============== R6·H1 상태줄 title 전수 (00-shell-1/2) ==============="
for f in 00-shell-1 00-shell-2; do
  G "$f.html"
  J "(()=>{return [...document.querySelectorAll('.state-wrapper')].map(w=>{const cells=[...w.querySelectorAll('.footer-statusbar .status-cell')].map(c=>'['+c.innerText.replace(/\s+/g,' ').trim()+'|'+c.title+']');return w.id+'('+cells.length+') '+cells.join(' ');}).join('\n');})()"
done

echo "=============== R3·H3 S5/S6 셀 버튼 px · 처리 중 · S6 상태줄 opener 왕복 ==============="
G 00-shell-2.html
J "(()=>{const s5=document.getElementById('state-s5');const bs=[...s5.querySelectorAll('button')].filter(b=>b.textContent.trim()==='다시 시작').map(b=>{const fs=getComputedStyle(b).fontSize;const inFoot=!!b.closest('.footer-statusbar');b.click();return (inFoot?'셀':'띠')+' '+fs+' → '+b.textContent.trim()+' disabled='+b.disabled;});const s6=document.getElementById('state-s6');const sb=[...s6.querySelectorAll('.footer-statusbar button')].find(b=>/자세히 보기/.test(b.textContent));const m=document.getElementById('modal-s6-update');sb.focus();sb.click();const open=getComputedStyle(m).display!=='none';const fin=m.contains(document.activeElement);const x=m.querySelector('.btn-modal-close-x,[aria-label*=닫기]');x.click();const back=document.activeElement===sb;const bb=[...s6.querySelectorAll('button')].find(b=>b.textContent.trim()==='업데이트');bb.click();const bl=bb.textContent.trim();document.querySelector('#state-s6 .btn-band-detail, #btn-open-s6-banner').click();const dl=[...m.querySelectorAll('button')].find(b=>b.textContent.trim()==='다운로드');dl.click();return 'S5 '+bs.join(' / ')+' | S6 셀 [자세히 보기] fs='+getComputedStyle(sb).fontSize+' open='+open+' focusIn='+fin+' ✕→focusBack='+back+' | 밴드 [업데이트]→'+bl+' | 모달 [다운로드]→'+dl.textContent.trim()+' disabled='+dl.disabled;})()"

echo "=============== R2 01-login-1 L1~L3 ==============="
G 01-login-1.html
J "(()=>{return ['l1','l2','l3'].map(id=>{const w=document.getElementById('state-'+id);const shell=w.querySelectorAll('.sidebar,.header-bar,.footer-statusbar,.btn-sidebar-toggle').length;const card=w.querySelector('.login-card,[class*=card]');const cw=card?Math.round(card.getBoundingClientRect().width):null;const labels=[...w.querySelectorAll('label')].map(l=>l.textContent.trim());const inputs=[...w.querySelectorAll('input')].map(i=>i.type+(i.value?'='+i.value:'')+(i.placeholder?'('+i.placeholder+')':'')+' border='+getComputedStyle(i).borderColor);const btns=[...w.querySelectorAll('button,a')].map(b=>(b.textContent.trim()||b.getAttribute('aria-label'))).filter(Boolean);const txt=w.innerText.replace(/\s+/g,' ').trim().slice(0,320);const small=[...w.querySelectorAll('*')].filter(e=>e.children.length===0&&e.textContent.trim()&&parseFloat(getComputedStyle(e).fontSize)<12).length;return id.toUpperCase()+' shell='+shell+' cardW='+cw+' labels='+labels.join(',')+' inputs='+inputs.join(' ; ')+' btns='+btns.join('|')+' <12px='+small+'\n   text: '+txt;}).join('\n');})()"
J "(()=>{const w=document.getElementById('state-l1');const i=w.querySelector('input[type=password]');const e=[...w.querySelectorAll('button')].find(b=>/표시|숨기기/.test(b.getAttribute('aria-label')||''));const t0=i.type,a0=e?e.getAttribute('aria-label'):'없음';if(e)e.click();return 'L1 눈 토글: '+t0+'('+a0+') → '+i.type+'('+(e?e.getAttribute('aria-label'):'')+') | 체크박스='+w.querySelectorAll('input[type=checkbox]').length+' | 일러스트(L3)='+document.querySelectorAll('#state-l3 [aria-hidden=true] .material-symbols-outlined, #state-l3 .material-symbols-outlined').length;})()"

echo "=============== R2 01-login-2 L4·L5 ==============="
G 01-login-2.html
J "(()=>{return ['l4','l5'].map(id=>{const w=document.getElementById('state-'+id);const shell=w.querySelectorAll('.sidebar,.header-bar,.footer-statusbar').length;const card=w.querySelector('[class*=card]');const cw=card?Math.round(card.getBoundingClientRect().width):null;const labels=[...w.querySelectorAll('label')].map(l=>l.textContent.trim());const inputs=[...w.querySelectorAll('input')].map(i=>i.type+(i.placeholder?'('+i.placeholder+')':''));const btns=[...w.querySelectorAll('button,a')].map(b=>(b.textContent.trim()||b.getAttribute('aria-label'))+(b.getAttribute('aria-disabled')==='true'?'[a-dis]':'')).filter(Boolean);const rules=[...w.querySelectorAll('li,[class*=rule]')].filter(e=>e.children.length<=2&&e.textContent.trim().length<20&&e.textContent.trim().length>3).map(e=>e.textContent.replace(/\s+/g,' ').trim()+'('+getComputedStyle(e).color+')');const txt=w.innerText.replace(/\s+/g,' ').trim().slice(0,300);return id.toUpperCase()+' shell='+shell+' cardW='+cw+' labels='+labels.join(',')+' inputs='+inputs.join(';')+' btns='+btns.join('|')+' rules='+[...new Set(rules)].join(' / ')+'\n   text: '+txt;}).join('\n');})()"
J "(()=>{const w=document.getElementById('state-l4');const b=[...w.querySelectorAll('button')].find(x=>x.textContent.trim()==='비밀번호 변경');const d=()=>{const x=document.getElementById(b.getAttribute('aria-describedby')||'');return x?(x.offsetParent!==null?x.textContent.trim()+' fs='+getComputedStyle(x).fontSize:'(숨김)'):'없음';};const ins=[...w.querySelectorAll('input')];const n=ins[1],c=ins[2];const set=(a,bb)=>{n.value=a;n.dispatchEvent(new Event('input',{bubbles:true}));c.value=bb;c.dispatchEvent(new Event('input',{bubbles:true}));};const r0='초기 aria-disabled='+b.getAttribute('aria-disabled')+' 사유='+d();set('Password123!','Password123!');const r1=' | 전부충족+일치: '+b.getAttribute('aria-disabled')+' 사유='+d();set('Password123!','Password123');const r2=' | 불일치: '+b.getAttribute('aria-disabled')+' 사유='+d();set('password','password');const r3=' | 미충족: '+b.getAttribute('aria-disabled')+' 사유='+d();b.click();return 'L4 게이트 '+r0+r1+r2+r3+' | 차단 클릭→ label='+b.textContent.trim();})()"
J "(()=>{const w=document.getElementById('state-l5');const ok=[...w.querySelectorAll('button')].find(x=>x.textContent.trim()==='확인');const i=w.querySelector('input');i.value='';i.dispatchEvent(new Event('input',{bubbles:true}));ok.click();const err=[...w.querySelectorAll('*')].filter(e=>e.children.length===0&&/계정복구키를 입력해주세요/.test(e.textContent)).map(e=>'\"'+e.textContent.trim()+'\" vis='+(e.offsetParent!==null)+' fs='+getComputedStyle(e).fontSize);const eye=[...w.querySelectorAll('button')].filter(b=>/표시|숨기기/.test(b.getAttribute('aria-label')||'')).length;return 'L5 빈값 [확인]→ 오류='+err.join(';')+' | 입력 필드 수='+w.querySelectorAll('input').length+' 눈 토글='+eye;})()"

echo "=============== N5·N11 G1·O4 권한 열 · R4 O2/O3 ==============="
G 12-access-logs-1.html
J "(()=>{const t=document.querySelector('#state-g1 table');const th=[...t.querySelectorAll('thead th')].map(x=>x.textContent.trim());const i=th.indexOf('권한');return 'G1 권한 열: '+[...t.tBodies[0].rows].map(r=>r.cells[i].textContent.trim()).join(',')+' | 행h='+Math.round(t.tBodies[0].rows[0].getBoundingClientRect().height);})()"
G 11-operations-2.html
J "(()=>{const t=document.querySelector('#state-o4 table');const th=[...t.querySelectorAll('thead th')].map(x=>x.textContent.trim());const i=th.indexOf('권한');const w=document.getElementById('state-o3');const card=[...w.querySelectorAll('[class*=card]')].find(e=>/요율 영향 미리보기/.test(e.textContent)&&e.textContent.length<700);return 'O4 권한 열: '+[...t.tBodies[0].rows].map(r=>r.cells[i].textContent.trim()).join(',')+' | O3 카드: '+(card?card.innerText.replace(/\s+/g,' ').trim().slice(0,260)+' btns='+[...card.querySelectorAll('button')].map(b=>b.textContent.trim()).join(','):'없음');})()"
G 11-operations-1.html
J "(()=>{const w=document.getElementById('state-o2');const h=[...w.querySelectorAll('*')].find(e=>e.children.length===0&&/전체 18건 중 8건 표시/.test(e.textContent));return 'O2 발췌: '+(h?'\"'+h.textContent.trim()+'\" fs='+getComputedStyle(h).fontSize+' vis='+(h.offsetParent!==null):'없음')+' | 행='+w.querySelectorAll('table tbody tr').length;})()"
echo DONE
